"""Reader of the generated boot-lite static config index (``config_lite_table.json``).

The index is generated by ``scripts/codegen/gen_config_lite_table.py`` — run it after any
config-field change; ``--check`` fails on drift. It is JSON, not a generated
Python module, because the all-field faces alone (512 fields x several columns)
exceed the repo's 800-line hard ceiling (``scripts/lint/code_structure.py``, no
exemption), and a data table is what JSON is for (precedent:
``base/lm/pricing/pricing_catalog_archive.json``). This module is the only reader; it
materializes the named surfaces every consumer imports:

- ``LITE_FIELDS`` — the boot-path fields ``base/config/_lite.py`` resolves
  without pydantic;
- ``FIELD_DOMAINS`` / ``FIELD_ALIASES`` / ``FIELD_SCOPES`` /
  ``FIELD_CAPABILITIES`` / ``PER_AGENT_FIELDS`` / ``SENSITIVE_FIELDS`` — the all-field indexes the
  facade accessors and ``base/host/env/registry.py``'s authority projections serve
  without building the registry;
- ``REQUIRED_FIELDS`` — the no-default fields ``_lite.prepare`` requires.

The module lives OUTSIDE the ``base.config`` package on purpose, like
``base/config/config_registry.py``: ``base/host/env/registry.py`` (the env-authority
projections that ``load_meiva_env`` runs before Settings exists) imports it, and a
package submodule import would execute the ``base.config`` facade first —
re-entering the boot it is part of.
"""

from __future__ import annotations

import json
import pkgutil
from collections.abc import Mapping
from dataclasses import dataclass
from types import MappingProxyType

from base.host.boundary.json_values import is_object_dict, is_object_list
from base.host.boundary.untyped import object_of

LiteField = tuple[str, str, str, str, object, str | None]


@dataclass(frozen=True)
class _Index:
    lite_fields: Mapping[str, LiteField]
    field_domains: Mapping[str, str]
    field_aliases: Mapping[str, str]
    field_scopes: Mapping[str, str]
    field_capabilities: Mapping[str, str]
    per_agent_fields: frozenset[str]
    sensitive_fields: frozenset[str]
    required_fields: frozenset[str]


# meiva:note
# One section of the index as a `str -> str` map. The generator writes these, so a section of any
# other shape is a stale or hand-edited index, and it stops the import with the section's name.
def _str_map(index: Mapping[str, object], section: str) -> dict[str, str]:
    value = index.get(section)
    if not is_object_dict(value) or not all(isinstance(item, str) for item in value.values()):
        raise TypeError(f"config_lite_table.json: {section} must map names to strings")
    return {name: item for name, item in value.items() if isinstance(item, str)}


def _str_set(index: Mapping[str, object], section: str) -> frozenset[str]:
    value = index.get(section)
    if not is_object_list(value) or not all(isinstance(item, str) for item in value):
        raise TypeError(f"config_lite_table.json: {section} must be a list of strings")
    return frozenset(item for item in value if isinstance(item, str))


# meiva:note
# One `lite_fields` row: (domain, env alias, parse kind, default kind, literal default, validity check).
def _lite_row(name: str, row: object) -> LiteField:
    if not is_object_list(row) or len(row) != 6:
        raise TypeError(f"config_lite_table.json: lite_fields[{name!r}] must be a 6-item list")
    domain, alias, parse_kind, default_kind, default, check = row
    if (
        not isinstance(domain, str)
        or not isinstance(alias, str)
        or not isinstance(parse_kind, str)
        or not isinstance(default_kind, str)
        or not (check is None or isinstance(check, str))
    ):
        raise TypeError(f"config_lite_table.json: lite_fields[{name!r}] has a mistyped column")
    return (domain, alias, parse_kind, default_kind, default, check)


def _read_index() -> tuple[
    Mapping[str, LiteField],
    Mapping[str, str],
    Mapping[str, str],
    Mapping[str, str],
    Mapping[str, str],
    frozenset[str],
    frozenset[str],
    frozenset[str],
]:
    """Parse once; only immutable index values survive the local JSON payload."""
    data = pkgutil.get_data(__package__ or "base.host.env", "config_lite_table.json")
    if data is None:
        raise FileNotFoundError("config_lite_table.json is missing from base.host.env")
    raw = object_of(json.loads, data.decode("utf-8"))
    if not is_object_dict(raw):
        raise TypeError("config_lite_table.json must hold a JSON object")
    lite = raw.get("lite_fields")
    if not is_object_dict(lite):
        raise TypeError("config_lite_table.json: lite_fields must be an object")
    return (
        MappingProxyType({name: _lite_row(name, row) for name, row in lite.items()}),
        MappingProxyType(_str_map(raw, "field_domains")),
        MappingProxyType(_str_map(raw, "field_aliases")),
        MappingProxyType(_str_map(raw, "field_scopes")),
        MappingProxyType(_str_map(raw, "field_capabilities")),
        _str_set(raw, "per_agent_fields"),
        _str_set(raw, "sensitive_fields"),
        _str_set(raw, "required_fields"),
    )


_INDEX = _Index(*_read_index())

# name: (domain, env alias, parse kind, default kind, literal default | None, validity check | None)
LITE_FIELDS: Mapping[str, LiteField] = _INDEX.lite_fields
FIELD_DOMAINS: Mapping[str, str] = _INDEX.field_domains
FIELD_ALIASES: Mapping[str, str] = _INDEX.field_aliases
# The env-authority pass (base/host/env/registry.py) reads these two without the registry.
FIELD_SCOPES: Mapping[str, str] = _INDEX.field_scopes
FIELD_CAPABILITIES: Mapping[str, str] = _INDEX.field_capabilities
PER_AGENT_FIELDS: frozenset[str] = _INDEX.per_agent_fields
SENSITIVE_FIELDS: frozenset[str] = _INDEX.sensitive_fields
# Fields with no default and no factory — the W1 required check in _lite.prepare().
REQUIRED_FIELDS: frozenset[str] = _INDEX.required_fields
